#include <cassert>
#include <cstdio>
#include <vector>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<int> values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (std::scanf("%d", &value) != 1) return 1;
        if (value < -100 || value > 100) return 1;
        values.push_back(value);
    }
    assert(static_cast<int>(values.size()) == n);
    int best = values[0];
    for (int value : values) {
        if (value > best) best = value;
    }
    std::printf("%d\n", best);
    return 0;
}
